import{_ as t,o as a,c as o,al as r}from"./chunks/framework.BKGVwAqU.js";const p=JSON.parse(`{"title":"Labor cost feed","description":"Give your own pricing or budgeting tool each project's labor cost at finish, with a key you can revoke, and keep fixed fees listed separately.","frontmatter":{"title":"Labor cost feed","description":"Give your own pricing or budgeting tool each project's labor cost at finish, with a key you can revoke, and keep fixed fees listed separately."},"headers":[],"relativePath":"guide/labor-cost-feed.md","filePath":"guide/labor-cost-feed.md"}`),s={name:"guide/labor-cost-feed.md"};function i(n,e,l,c,d,h){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="labor-cost-feed" tabindex="-1">Labor cost feed <a class="header-anchor" href="#labor-cost-feed" aria-label="Permalink to &quot;Labor cost feed&quot;">​</a></h1><p>You can let your own tool, such as a pricing calculator, read every project&#39;s labor cost from VERA. VERA only sends; it never receives anything or changes anything.</p><p>Owners and admins manage it in <strong>Settings → General → Labor cost feed</strong>.</p><h2 id="what-the-figure-is" tabindex="-1">What the figure is <a class="header-anchor" href="#what-the-figure-is" aria-label="Permalink to &quot;What the figure is&quot;">​</a></h2><p>A project&#39;s labor cost is what its people will have cost by the time it&#39;s finished: the time recorded so far, each hour at the person&#39;s cost rate on the day it was recorded, plus the hours still left on each person&#39;s allocation at their current rate.</p><p>For example, someone at $10 an hour has a 10-hour allocation and nothing is recorded yet: the labor cost is $100. A colleague at $15 an hour then records an hour with no allocation of their own: the labor cost is $115, $15 recorded and $100 still to come. If the first person records 4 hours, it&#39;s $55 recorded and $60 to come, still $115. Time recorded beyond an allocation adds to the total; it never lowers it.</p><p>Every project is listed, whatever its status. Proposals are not.</p><h2 id="fixed-fees-are-listed-separately" tabindex="-1">Fixed fees are listed separately <a class="header-anchor" href="#fixed-fees-are-listed-separately" aria-label="Permalink to &quot;Fixed fees are listed separately&quot;">​</a></h2><p>Flat amounts agreed with a vendor or a contractor are never part of the labor cost. Each project lists them on their own, with a total, so your tool can count them with its other cost of goods sold. The feed also gives each project a total cost: labor plus fixed fees.</p><h2 id="keys" tabindex="-1">Keys <a class="header-anchor" href="#keys" aria-label="Permalink to &quot;Keys&quot;">​</a></h2><p>Create a key with a name, such as &quot;Pricing calculator&quot;. VERA shows it once; copy it then. Give it only to tools you trust, because a key can read every project&#39;s figures. To stop a tool, revoke its key. The list shows when each key was last used.</p><h2 id="build-the-receiving-side" tabindex="-1">Build the receiving side <a class="header-anchor" href="#build-the-receiving-side" aria-label="Permalink to &quot;Build the receiving side&quot;">​</a></h2><p>Settings shows instructions you can paste into your AI assistant. It reads them and builds the receiving side for whatever your tool runs on. You can also open the instructions as a page.</p>',13)])])}const f=t(s,[["render",i]]);export{p as __pageData,f as default};
